  var REFRACT = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="空気から水へ進む光の屈折。屈折角は入射角より小さい"><rect x="10" y="75" width="200" height="70" class="fl"/><line x1="10" y1="75" x2="210" y2="75" class="ax"/><line x1="110" y1="10" x2="110" y2="145" class="dash"/><line x1="50" y1="15" x2="110" y2="75" class="cv"/><line x1="110" y1="75" x2="140" y2="140" class="cv"/><path d="M110 55 A20 20 0 0 0 95.9 60.9" class="arc"/><path d="M110 95 A20 20 0 0 0 118.4 93.2" class="arc"/><text x="16" y="68">空気</text><text x="16" y="92">水</text><text x="38" y="52">入射角</text><text x="122" y="106">屈折角</text><text x="128" y="30">入射角 &gt; 屈折角</text></svg>';
